/* De Stijl 0.3.0 — DESTIJL_STYLE.md §1, §1b, §2, §3, §7. github.com/byronshock/destijl_theme_kit */
:root {
  --ds-white:    #E5E6E8;
  --ds-light:    #9C9EA0;
  --ds-dark:     #535758;
  --ds-black:    #0A0F10;
  --ds-yellow:   #DFCC82;
  --ds-yellow-2: #988D5C;
  --ds-yellow-1: #514E36;
  --ds-blue:     #1B3A6D;
  --ds-blue-2:   #152C4E;
  --ds-red:      #D64D24;
  --ds-destructive: #AF1E2D;
  --ds-rule: 28px;
  --ds-ui:   "Nimbus Sans", "Helvetica Neue", Helvetica, Arial, sans-serif;
  --ds-mono: Hack, "DejaVu Sans Mono", monospace;
}

/* ---------- geometry ---------- */
*, *::before, *::after {
  border-radius: 0 !important;
  box-shadow: none !important;
  text-shadow: none !important;
}
input, textarea, select, button, fieldset, table, td, th, tr, blockquote, dialog, details, summary, nav, header, footer, aside, section, article, main, figure, [role="dialog"], [role="menu"], [role="listbox"], [role="toolbar"], [role="tablist"], [role="tab"] {
  border-color: transparent !important;
  border-width: 0 !important;
}
hr {
  border: 0 !important;
  height: var(--ds-rule) !important;
  background: var(--ds-black) !important;
  margin: var(--ds-rule) 0 !important;
}

/* ---------- ground ---------- */
html, body {
  background: var(--ds-white) !important;
  color: var(--ds-black) !important;
  -webkit-text-fill-color: currentcolor !important;
}
body *:not(img):not(video):not(canvas):not(svg):not(iframe):not(picture):not(source):not(embed):not(object) {
  background-image: none !important;
  background-color: transparent;
  color: var(--ds-black);
  -webkit-text-fill-color: currentcolor;
}
svg, svg * {
  background-image: initial;
  color: inherit;
  -webkit-text-fill-color: inherit;
}

/* the field: LIGHT */
header, footer, nav, form, thead, th, blockquote, figcaption, summary, [role="banner"], [role="contentinfo"], [role="navigation"], [role="toolbar"], [role="tablist"], [role="search"] {
  background-color: var(--ds-light) !important;
  color: var(--ds-black) !important;
}
/* documents: WHITE */
main, article, section, table, tbody, td, dialog, details, [role="main"], [role="article"], [role="region"], [role="document"], [role="dialog"], [role="menu"], [role="listbox"], [role="tooltip"] {
  background-color: var(--ds-white) !important;
  color: var(--ds-black) !important;
}
/* wells: LIGHT on a document, WHITE on a field */
input, textarea, select, pre, code, kbd, samp, [role="textbox"], [role="combobox"], [role="searchbox"] {
  background-color: var(--ds-light) !important;
  color: var(--ds-black) !important;
  -webkit-text-fill-color: var(--ds-black) !important;
}
form input, form textarea, form select, header input, nav input, footer input, form [role="textbox"], header [role="searchbox"], nav [role="searchbox"], [role="search"] input, th code, blockquote code {
  background-color: var(--ds-white) !important;
}
:disabled, [aria-disabled="true"] {
  color: var(--ds-dark) !important;
  -webkit-text-fill-color: var(--ds-dark) !important;
}

/* sidebars: blue, yellow on it (7.0:1); the highlighted item WHITE on blue-2 (11.2:1) */
